'use client';
import { useLayoutEffect, RefObject } from 'react';
import { gsap, conscious } from './motion-config';

export function useReveals(ref: RefObject<HTMLElement>) {
  useLayoutEffect(() => {
    if (conscious.reduced || !ref.current) return;
    const ctx = gsap.context(() => {
      gsap.utils.toArray<HTMLElement>('[data-reveal]', ref.current).forEach((el) => {
        gsap.from(el, {
          y: 40, autoAlpha: 0, duration: 1, ease: 'power4.out',
          delay: parseFloat(el.dataset.reveal || '0'),
          scrollTrigger: { trigger: el, start: 'top 88%', once: true },
        });
      });
    }, ref);
    return () => ctx.revert();
  }, [ref]);
}
