'use client';
import { useLayoutEffect, useRef, useState } from 'react';
import { gsap, ScrollTrigger, conscious } from '@/lib/motion-config';

const NODES = [
  { id: 'inicio', label: 'Inicio' },
  { id: 'problema', label: 'Problema' },
  { id: 'metodo', label: 'Método' },
  { id: 'servicios', label: 'Servicios' },
  { id: 'cta', label: 'Contacto' },
];

export default function Nav() {
  const [active, setActive] = useState(0);
  const navRef = useRef<HTMLElement>(null);
  const progressRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    if (conscious.reduced) return;
    const ctx = gsap.context(() => {
      // Ocultar al bajar, mostrar al subir
      ScrollTrigger.create({
        start: 0, end: 'max',
        onUpdate: (self) => {
          if (self.direction === 1 && self.scroll() > 300)
            gsap.to(navRef.current, { yPercent: -100, duration: 0.4, ease: 'power3' });
          else
            gsap.to(navRef.current, { yPercent: 0, duration: 0.4, ease: 'power3' });
        },
      });

      // Progreso de scroll
      gsap.fromTo(progressRef.current, { scaleX: 0 }, {
        scaleX: 1, ease: 'none',
        scrollTrigger: { start: 0, end: 'max', scrub: 0.4 },
      });

      // La web sabe dónde estás: enciende el nodo de la sección activa
      NODES.forEach((n, i) => {
        const el = document.getElementById(n.id);
        if (!el) return;
        ScrollTrigger.create({
          trigger: el, start: 'top center', end: 'bottom center',
          onToggle: (self) => { if (self.isActive) setActive(i); },
        });
      });
    });
    return () => ctx.revert();
  }, []);

  return (
    <header
      ref={navRef}
      className="fixed top-0 inset-x-0 z-[80] bg-abismo/70 backdrop-blur-md border-b border-white/5"
    >
      <nav className="flex items-center justify-between px-6 md:px-12 h-16" aria-label="Principal">
