'use client';
import { useLayoutEffect, useRef } from 'react';
import SplitType from 'split-type';
import { gsap, conscious } from '@/lib/motion-config';
import PageHeader from '@/components/PageHeader';

const TEXTO = `Una empresa no es solamente un conjunto de herramientas. Es un conjunto de personas, decisiones, información y procesos que se conectan entre sí. Por eso no empezamos preguntando qué software quieres. Preguntamos qué intentas conseguir y cómo lo haces actualmente. No vendemos inteligencia artificial: puede formar parte de una solución, pero no es el producto. No todo debe automatizarse: las decisiones importantes, la relación humana, el criterio profesional y aquello que requiere responsabilidad pueden y deben permanecer en manos de personas. A partir de ahí, construimos.`;

export default function PrincipiosPage() {
  const ref = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLParagraphElement>(null);

  useLayoutEffect(() => {
    if (conscious.reduced || !textRef.current) return;
    const words = textRef.current.innerText.split(' ');
    textRef.current.innerHTML = words
      .map((w) => `<span style="display:inline-block;margin-right:.28em;color:rgba(245,243,239,.14)">${w}</span>`)
      .join('');
    const els = textRef.current.querySelectorAll('span');
    const tl = gsap.to(els, {
      color: 'rgba(245,243,239,1)', ease: 'none', stagger: 0.02,
      scrollTrigger: { trigger: textRef.current, start: 'top 75%', end: 'bottom 40%', scrub: 0.8 },
    });
    return () => { tl.scrollTrigger?.kill(); tl.kill(); };
  }, []);

  return (
    <div ref={ref} className="px-6 md:px-12 max-w-5xl mx-auto pb-32">
      <PageHeader kicker="El principio CIRCUIT" title="Manifiesto" />
      <p ref={textRef} className="font-display font-light text-2xl md:text-4xl leading-relaxed">
        {TEXTO}
      </p>
      <p className="mt-16 font-mono text-ambar text-sm tracking-[0.3em] uppercase">
        No cambio tu negocio. Cambio la forma en que funciona por dentro.
      </p>
    </div>
  );
}
