```js
// motion/core.js
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import Lenis from 'lenis'

gsap.registerPlugin(ScrollTrigger)

export const consciente = {
  reduced: matchMedia('(prefers-reduced-motion: reduce)').matches,
  saveData: navigator.connection?.saveData ?? false,
  tactil: matchMedia('(pointer: coarse)').matches,
}

export function initScroll() {
  if (consciente.reduced) return null
  const lenis = new Lenis({ lerp: 0.09 })
  lenis.on('scroll', ScrollTrigger.update)
  gsap.ticker.add(t => lenis.raf(t * 1000))
  gsap.ticker.lagSmoothing(0)
  return lenis
}

// Modo estático: si el usuario pide menos movimiento,
// la web obedece y muestra todo, ya, sin teatro.
if (consciente.reduced) {
  document.documentElement.classList.add('is-static')
}
```

