## VIII. MICROINTERACCIONES GLOBALES

### 8.1 Cursor instrumento

```js
// motion/cursor.js
export function initCursor() {
  if (consciente.tactil || consciente.reduced) return
  const dot = document.querySelector('#cursor-dot')
  const ring = document.querySelector('#cursor-ring')

  const dx = gsap.quickTo(dot, 'x', { duration: .12, ease: 'power2' })
  const dy = gsap.quickTo(dot, 'y', { duration: .12, ease: 'power2' })
  const rx = gsap.quickTo(ring, 'x', { duration: .45, ease: 'power3' })
  const ry = gsap.quickTo(ring, 'y', { duration: .45, ease: 'power3' })

  addEventListener('pointermove', e => {
    dx(e.clientX); dy(e.clientY); rx(e.clientX); ry(e.clientY)
  })

  // estados conscientes: el anillo entiende lo que toca
  document.querySelectorAll('a, button, [data-hover]').forEach(el => {
    el.addEventListener('pointerenter', () => ring.classList.add('is-active'))
    el.addEventListener('pointerleave', () => ring.classList.remove('is-active'))
  })
}
```

CSS: punto 4px ámbar; anillo 36px, borde 1px blanco al 30%, `mix-blend-mode: difference`; `.is-active` escala a 64px y vira a ámbar.

### 8.2 Botones magnéticos

```js
export function initMagnetic() {
  if (consciente.tactil || consciente.reduced) return
  document.querySelectorAll('[data-magnetic]').forEach(el => {
    const x = gsap.quickTo(el, 'x', { duration: .4, ease: 'power3' })
    const y = gsap.quickTo(el, 'y', { duration: .4, ease: 'power3' })
    el.addEventListener('pointermove', e => {
      const r = el.getBoundingClientRect()
      x((e.clientX - r.left - r.width / 2) * .3)
      y((e.clientY - r.top - r.height / 2) * .3)
    })
    el.addEventListener('pointerleave', () => { x(0); y(0) })
  })
}
```

### 8.3 Scramble / decode

```js
const GLYPHS = '█▓▒░/\\<>—·01'
export function scramble(el, final, dur = 700) {
  if (consciente.reduced) { el.textContent = final; return }
  const start = performance.now()
  ;(function tick(now) {
    const p = Math.min((now - start) / dur, 1)
    el.textContent = [...final].map((c, i) =>
      i < p * final.length ? c : GLYPHS[Math.random() * GLYPHS.length | 0]).join('')
    if (p < 1) requestAnimationFrame(tick)
  })(start)
}
```

