# V. IMPLEMENTACIÓN DE LOS "MOMENTOS FIRMA"

### 1. El Manifiesto (Iluminación por Scroll)
El texto está en la pantalla, pero "dormido" (opacidad 14%). Al hacer scroll, las palabras se encienden secuencialmente.

```tsx
// src/components/sections/Manifesto.tsx
"use client";
import { useLayoutEffect, useRef } from 'react';
import { gsap, ScrollTrigger } from '@/lib/motion-config';

export default function Manifesto() {
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLParagraphElement>(null);

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      const text = textRef.current;
      if (!text) return;

      // Split manual para evitar dependencias pesadas en este ejemplo
      const words = text.innerText.split(' ');
      text.innerHTML = words.map(w => `<span class="word" style="display:inline-block; margin-right:0.25em; color: rgba(245,243,239,0.14);">${w}</span>`).join('');

      const wordEls = text.querySelectorAll('.word');

      gsap.to(wordEls, {
        color: 'rgba(245,243,239,1)',
        ease: 'none',
        stagger: 0.05,
        scrollTrigger: {
          trigger: containerRef.current,
          start: 'top 75%',
          end: 'bottom 40%',
          scrub: 1,
        }
      });
    }, containerRef);

    return () => ctx.revert();
  }, []);

  return (
    <section ref={containerRef} className="min-h-screen flex items-center justify-center px-6 py-32">
      <p ref={textRef} className="max-w-4xl text-3xl md:text-5xl font-display font-light leading-tight tracking-tight">
        No vendemos inteligencia artificial. No vendemos automatización por automatizar. A veces la mejor solución es eliminar cinco pasos. Nuestra responsabilidad es encontrar la solución adecuada. No recomendamos tecnología hasta entender el proceso.
      </p>
    </section>
  );
}
```

### 2. El Método (Scroll Horizontal Pinned)
La sección se "clava" (pin) en la pantalla y el scroll vertical se traduce en movimiento horizontal a través de los 5 nodos del circuito.

```tsx
// src/components/sections/Method.tsx
"use client";
import { useLayoutEffect, useRef } from 'react';
import { gsap, ScrollTrigger } from '@/lib/motion-config';

const phases = [
  { num: '01', title: 'Mapear', desc: 'Observamos y representamos cómo funciona el circuito.' },
  { num: '02', title: 'Detectar', desc: 'Buscamos las zonas donde el circuito pierde eficiencia.' },
  { num: '03', title: 'Rediseñar', desc: 'Decidimos qué eliminar, simplificar o automatizar.' },
  { num: '04', title: 'Implementar', desc: 'Construimos el nuevo circuito sin fricción.' },
  { num: '05', title: 'Medir', desc: 'Demostramos que funciona con datos reales.' },
];

export default function Method() {
  const containerRef = useRef<HTMLDivElement>(null);
  const panelsRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      const panels = gsap.utils.toArray<HTMLElement>('.panel');

      gsap.to(panels, {
        xPercent: -100 * (panels.length - 1),
        ease: 'none',
        scrollTrigger: {
          trigger: containerRef.current,
          pin: true,
          scrub: 1,
          end: () => '+=' + (window.innerWidth * (panels.length - 1) * 0.8),
        }
      });
    }, containerRef);

    return () => ctx.revert();
  }, []);

  return (
    <section ref={containerRef} className="h-screen overflow-hidden relative">
      <div ref={panelsRef} className="flex h-full w-[500vw]">
        {phases.map((p, i) => (
          <div key={i} className="panel w-screen h-full flex flex-col justify-center items-center px-8">
            <span className="font-mono text-[var(--ambar-senal)] text-sm mb-4">{p.num}</span>
            <h2 className="text-6xl md:text-8xl font-display font-medium mb-6">{p.title}</h2>
            <p className="max-w-md text-center text-[var(--gris-neblina)] text-lg">{p.desc}</p>
          </div>
        ))}
      </div>
    </section>
  );
}
```

### 3. Rediseñar (El Circuito se Cura)
Transición SVG donde las líneas caóticas (rojas/grises) se desvanecen y la línea optimizada (ámbar) se dibuja a sí misma.

```tsx
// src/components/sections/Redesign.tsx
"use client";
import { useLayoutEffect, useRef } from 'react';
import { gsap, ScrollTrigger } from '@/lib/motion-config';

export default function Redesign() {
  const sectionRef = useRef<HTMLElement>(null);

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      const tl = gsap.timeline({
        scrollTrigger: {
          trigger: sectionRef.current,
          start: 'top 60%',
          end: 'bottom 40%',
          scrub: 1,
        }
      });

      // El caos se retira
      tl.to('.path-chaos', { strokeDashoffset: 1000, opacity: 0, ease: 'none' }, 0);
      tl.to('.node-chaos', { scale: 0, opacity: 0, stagger: 0.05, ease: 'power2.in' }, 0);

      // El orden emerge
      tl.fromTo('.path-order', 
        { strokeDashoffset: 1000 }, 
        { strokeDashoffset: 0, ease: 'none' }, 
        0.2
      );
      tl.from('.node-order', { 
        scale: 0, 
        stagger: 0.1, 
        ease: 'back.out(2)' 
      }, 0.5);

    }, sectionRef);

    return () => ctx.revert();
  }, []);

  return (
    <section ref={sectionRef} className="min-h-screen flex items-center justify-center p-8">
      <div className="w-full max-w-4xl aspect-[16/9] relative border border-white/5 rounded-lg bg-[var(--negro-superficie)] overflow-hidden">
        <svg viewBox="0 0 800 400" className="w-full h-full">
          {/* Circuito Caótico */}
          <path className="path-chaos" d="M50,200 C150,50 250,350 400,200 S650,50 750,200" fill="none" stroke="#EF4444" strokeWidth="2" strokeDasharray="1000" strokeDashoffset="0" opacity="0.6"/>
          <circle className="node-chaos" cx="200" cy="150" r="6" fill="#EF4444" />
          <circle className="node-chaos" cx="600" cy="250" r="6" fill="#EF4444" />

          {/* Circuito Optimizado */}
          <path className="path-order" d="M50,200 L750,200" fill="none" stroke="var(--ambar-senal)" strokeWidth="3" strokeDasharray="1000" strokeDashoffset="1000" />
          <circle className="node-order" cx="225" cy="200" r="8" fill="var(--ambar-senal)" />
          <circle className="node-order" cx="400" cy="200" r="8" fill="var(--ambar-senal)" />
          <circle className="node-order" cx="575" cy="200" r="8" fill="var(--ambar-senal)" />
        </svg>
      </div>
    </section>
  );
}
