.btn-liquid { position: relative; overflow: hidden; isolation: isolate; transition: color .4s var(--ease-out); }
.btn-liquid::before {
  content: ''; position: absolute; inset: 0; z-index: -1;
  background: var(--ambar-senal); transform: translateY(102%);
  transition: transform .6s var(--ease-inout);
}
.btn-liquid:hover::before, .btn-liquid:focus-visible::before { transform: translateY(0); }
.btn-liquid:hover, .btn-liquid:focus-visible { color: #0A0A0B; }

/* ---- Web consciente: reduced motion ---- */
.is-static *, .is-static *::before, .is-static *::after {
  animation: none !important; transition: none !important;
}
.is-static [data-reveal], .is-static .line-mask > * {
  opacity: 1 !important; transform: none !important;
}
.is-static #preloader { display: none !important; }

/* ---- Degradación elegante ---- */
.performance-degraded canvas { display: none !important; }
.performance-degraded {
  background: radial-gradient(1200px 800px at 70% 15%, #141416 0%, #0A0A0B 60%);
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .01ms !important; animation-iteration-count: 1 !important;
    transition-duration: .01ms !important; scroll-behavior: auto !important;
  }
  body::after, #cursor-dot, #cursor-ring { display: none; }
