'use client';
import { useLayoutEffect, useRef } from 'react';
import { gsap, conscious } from '@/lib/motion-config';

export default function Preloader() {
  const ref = useRef<HTMLDivElement>(null);
  const numRef = useRef<HTMLSpanElement>(null);

  useLayoutEffect(() => {
    document.documentElement.classList.add('is-loading');
    window.scrollTo(0, 0);

    const finish = () => {
      document.documentElement.classList.remove('is-loading');
      document.documentElement.classList.add('is-loaded');
      window.dispatchEvent(new Event('circuit:ready'));
    };

    if (conscious.reduced || !ref.current) {
      ref.current?.remove();
      finish();
      return;
    }

    const state = { n: 0 };
    const tl = gsap.timeline({ onComplete: () => { ref.current?.remove(); finish(); } });

    tl.to(state, {
      n: 100, duration: 1.4, ease: 'power2.inOut',
      onUpdate: () => {
        if (numRef.current)
          numRef.current.textContent = String(Math.round(state.n)).padStart(3, '0');
      },
    })
    .to(ref.current, { clipPath: 'inset(0 0 100% 0)', duration: 1, ease: 'power4.inOut' }, '+=0.15');

    return () => { tl.kill(); };
  }, []);

  return (
    <div
      id="preloader"
      ref={ref}
      aria-hidden="true"
      className="fixed inset-0 z-[100] bg-abismo flex flex-col items-center justify-center gap-6"
      style={{ clipPath: 'inset(0 0 0% 0)' }}
    >
      <span className="font-mono text-xs tracking-[0.4em] text-neblina uppercase">CIRCUIT</span>
      <span ref={numRef} className="font-mono text-ambar text-4xl tabular-nums">000</span>
