'use client';
import { useLayoutEffect, useRef } from 'react';
import { gsap, conscious } from '@/lib/motion-config';

export default function CustomCursor() {
  const dotRef = useRef<HTMLDivElement>(null);
  const ringRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    if (conscious.coarse || conscious.reduced) return;

    const dot = dotRef.current!, ring = ringRef.current!;
    const dx = gsap.quickTo(dot, 'x', { duration: 0.12, ease: 'power2' });
    const dy = gsap.quickTo(dot, 'y', { duration: 0.12, ease: 'power2' });
    const rx = gsap.quickTo(ring, 'x', { duration: 0.45, ease: 'power3' });
    const ry = gsap.quickTo(ring, 'y', { duration: 0.45, ease: 'power3' });

    const move = (e: PointerEvent) => {
      dx(e.clientX); dy(e.clientY); rx(e.clientX); ry(e.clientY);
    };
    const enter = () => ring.classList.add('is-active');
    const leave = () => ring.classList.remove('is-active');

    window.addEventListener('pointermove', move);
    const targets = document.querySelectorAll('a, button, [data-hover]');
    targets.forEach((el) => {
      el.addEventListener('pointerenter', enter);
      el.addEventListener('pointerleave', leave);
    });

    return () => {
      window.removeEventListener('pointermove', move);
      targets.forEach((el) => {
        el.removeEventListener('pointerenter', enter);
        el.removeEventListener('pointerleave', leave);
      });
    };
  }, []);

  if (conscious.coarse || conscious.reduced) return null;

  return (
    <>
      <div id="cursor-dot" ref={dotRef} aria-hidden="true" />
      <div id="cursor-ring" ref={ringRef} aria-hidden="true" />
    </>
  );
}
